-- StudyOS migration 0001: academic structure foundation.
--
-- Conventions
--   * Primary keys are UUID strings generated by the application.
--   * Timestamps are ISO-8601 UTC strings; calendar dates are YYYY-MM-DD.
--   * User-owned entities are soft-deleted via `deleted_at`.
--   * JSON columns are validated by the application layer.

-- Key/value application settings (theme, active programme, ...).
CREATE TABLE settings (
    key        TEXT PRIMARY KEY NOT NULL,
    value      TEXT NOT NULL,
    updated_at TEXT NOT NULL
);

-- The single local user of this StudyOS installation.
CREATE TABLE user_profile (
    id           INTEGER PRIMARY KEY CHECK (id = 1),
    display_name TEXT NOT NULL DEFAULT '',
    created_at   TEXT NOT NULL,
    updated_at   TEXT NOT NULL
);

CREATE TABLE institutions (
    id         TEXT PRIMARY KEY NOT NULL,
    name       TEXT NOT NULL CHECK (length(trim(name)) > 0),
    kind       TEXT NOT NULL DEFAULT 'university'
               CHECK (kind IN ('university', 'college', 'school', 'online', 'certification', 'other')),
    country    TEXT,
    website    TEXT,
    notes      TEXT,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    deleted_at TEXT
);
CREATE INDEX idx_institutions_active ON institutions (deleted_at, name);

-- A degree, diploma, certification or self-learning track.
CREATE TABLE programmes (
    id               TEXT PRIMARY KEY NOT NULL,
    institution_id   TEXT NOT NULL REFERENCES institutions (id) ON DELETE CASCADE,
    name             TEXT NOT NULL CHECK (length(trim(name)) > 0),
    level            TEXT NOT NULL DEFAULT 'bachelor'
                     CHECK (level IN ('school', 'diploma', 'bachelor', 'master', 'doctorate', 'certification', 'course', 'self_learning', 'other')),
    status           TEXT NOT NULL DEFAULT 'active'
                     CHECK (status IN ('planned', 'active', 'completed', 'paused', 'withdrawn')),
    field            TEXT,
    start_date       TEXT,
    end_date         TEXT,
    total_credits    REAL CHECK (total_credits IS NULL OR total_credits >= 0),
    credit_unit      TEXT NOT NULL DEFAULT 'ECTS',
    grading_scale    TEXT NOT NULL,           -- JSON GradingScale
    target_grade     REAL,                    -- on the programme's grading scale
    color            TEXT,
    notes            TEXT,
    created_at       TEXT NOT NULL,
    updated_at       TEXT NOT NULL,
    deleted_at       TEXT
);
CREATE INDEX idx_programmes_institution ON programmes (institution_id, deleted_at);
CREATE INDEX idx_programmes_status ON programmes (status, deleted_at);

CREATE TABLE academic_years (
    id           TEXT PRIMARY KEY NOT NULL,
    programme_id TEXT NOT NULL REFERENCES programmes (id) ON DELETE CASCADE,
    label        TEXT NOT NULL CHECK (length(trim(label)) > 0),
    start_date   TEXT,
    end_date     TEXT,
    sort_order   INTEGER NOT NULL DEFAULT 0,
    created_at   TEXT NOT NULL,
    updated_at   TEXT NOT NULL,
    deleted_at   TEXT
);
CREATE INDEX idx_academic_years_programme ON academic_years (programme_id, deleted_at, sort_order);

-- Semester, term, trimester, quarter or module block.
CREATE TABLE semesters (
    id               TEXT PRIMARY KEY NOT NULL,
    academic_year_id TEXT NOT NULL REFERENCES academic_years (id) ON DELETE CASCADE,
    label            TEXT NOT NULL CHECK (length(trim(label)) > 0),
    start_date       TEXT,
    end_date         TEXT,
    sort_order       INTEGER NOT NULL DEFAULT 0,
    created_at       TEXT NOT NULL,
    updated_at       TEXT NOT NULL,
    deleted_at       TEXT
);
CREATE INDEX idx_semesters_year ON semesters (academic_year_id, deleted_at, sort_order);
CREATE INDEX idx_semesters_dates ON semesters (start_date, end_date);

CREATE TABLE courses (
    id           TEXT PRIMARY KEY NOT NULL,
    programme_id TEXT NOT NULL REFERENCES programmes (id) ON DELETE CASCADE,
    semester_id  TEXT REFERENCES semesters (id) ON DELETE SET NULL,
    name         TEXT NOT NULL CHECK (length(trim(name)) > 0),
    code         TEXT,
    credits      REAL CHECK (credits IS NULL OR credits >= 0),
    lecturer     TEXT,
    lecturer_email TEXT,
    location     TEXT,
    status       TEXT NOT NULL DEFAULT 'in_progress'
                 CHECK (status IN ('planned', 'in_progress', 'completed', 'dropped')),
    final_grade  REAL,                         -- on the programme's grading scale
    target_grade REAL,
    color        TEXT,
    description  TEXT,
    created_at   TEXT NOT NULL,
    updated_at   TEXT NOT NULL,
    deleted_at   TEXT
);
CREATE INDEX idx_courses_programme ON courses (programme_id, deleted_at);
CREATE INDEX idx_courses_semester ON courses (semester_id, deleted_at);
CREATE INDEX idx_courses_status ON courses (status, deleted_at);

-- Tags are global and attach to any entity through entity_tags.
CREATE TABLE tags (
    id         TEXT PRIMARY KEY NOT NULL,
    name       TEXT NOT NULL COLLATE NOCASE UNIQUE CHECK (length(trim(name)) > 0),
    color      TEXT,
    created_at TEXT NOT NULL
);

CREATE TABLE entity_tags (
    tag_id      TEXT NOT NULL REFERENCES tags (id) ON DELETE CASCADE,
    entity_type TEXT NOT NULL,
    entity_id   TEXT NOT NULL,
    created_at  TEXT NOT NULL,
    PRIMARY KEY (tag_id, entity_type, entity_id)
);
CREATE INDEX idx_entity_tags_entity ON entity_tags (entity_type, entity_id);

